mapper.select:
SELECT format_version, action, disposition, reason_code, occurred_at, actor_ref,
       request_correlation, requirement_code, status_transition, evidence_identity_hash,
       subject_fingerprint, assessment_hash
  FROM readiness_audit
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND environment = #{environment}
 ORDER BY audit_id ASC
